from lib import *
S = SS('w94')
steps = [
    step("本机搭一套临时的小 PKI(全是脚本生成、只在本机用):CA “w94 Test CA”签发服务器证书(CN=localhost,SAN localhost,extendedKeyUsage 为 serverAuth)和客户端证书 alice(extendedKeyUsage 为 clientAuth)。另外还有“另一个 CA(w94 Other CA)”签发的客户端证书 mallory,服务器并不信任这个 CA;以及 CA 签发但有效期是 10-05 ~ 10-07、已经过期的客户端证书 bob。(我第一次生成证书时没有加 Authority Key Identifier 和 Subject Key Identifier 扩展,Python 3.13 之后默认的严格 X.509 校验会因此拒绝所有证书——报 “Missing Authority Key Identifier”;补上这些扩展才跑通。自己签测试证书的人常会撞上这一条。)", t=tl(S(1)), mark=lidx(S(1), 'CA:CN=w94 Test CA'), done=lidx(S(1), 'mallory 的证书'), kv=KV([['CA', 'w94 Test CA(服务器信任它)'], ['alice', 'CA 签发,clientAuth,有效'], ['mallory', '另一个 CA 签发,不被信任'], ['bob', 'CA 签发,已过期']], ['alice'])),
    step("服务器要求客户端证书(CERT_REQUIRED,只信任 w94 Test CA)。alice → 握手 1.7 ms 成功,收到 “hello alice@w94”,服务器记录的对方身份是 alice@w94。不带任何客户端证书 → 客户端握手 1.1 ms 看起来成功了,但第一次读就报 TLSV13_ALERT_CERTIFICATE_REQUIRED;服务器那边报 PEER_DID_NOT_RETURN_A_CERTIFICATE。mallory(由不被信任的 CA 签发)→ 客户端第一次读报 TLSV1_ALERT_UNKNOWN_CA;服务器报 CERTIFICATE_VERIFY_FAILED。bob(已过期)→ 客户端第一次读报 SSLV3_ALERT_CERTIFICATE_EXPIRED。关键细节:在 TLS 1.3 里,客户端的证书是在客户端这边“握手完成”之后才被服务器验证的,所以客户端的 wrap_socket 已经返回成功,错误要到第一次读写才以警报的形式出现——客户端要处理好这个“假成功”。", t=tl(S(2)), mark=lidx(S(2), '不带任何客户端证书', 'mallory', 'bob'), done=lidx(S(2), 'alice(有效的客户端证书)'), kv=KV([['有效证书', '握手成功,服务器知道对方是 alice@w94'], ['不带证书', '握手 “成功” 但第一次读失败:certificate required'], ['不被信任的 CA', '第一次读失败:unknown ca'], ['已过期', '第一次读失败:certificate expired']], ['不带证书'])),
    step("服务器“可选”客户端证书(CERT_OPTIONAL):alice → 成功,服务器记录身份 alice@w94;不带证书 → 也成功,服务器记录的身份是 None,收到 “hello anonymous”——让不让进、能干什么,由应用层根据“有没有证书”决定;mallory(出示了证书但 CA 不被信任)→ 失败,第一次读报 unknown ca。所以可选模式的规则是:不出示可以,出示了就必须有效。", t=tl(S(3)), mark=lidx(S(3), 'alice     →', '不带证书', 'mallory   →'), done=lidx(S(3), 'alice     →'), kv=KV([['出示有效证书', '成功,身份 alice@w94'], ['不出示', '成功,身份 None(anonymous)'], ['出示无效证书', '失败:unknown ca']], ['不出示'])),
    step("客户端证书在线上能不能被看到?抓 lo0 上两次带客户端证书的握手。TLS 1.2:客户端→服务器 1232 字节,握手消息依次是 ClientHello、Certificate、ClientKeyExchange、CertificateVerify、ChangeCipherSpec;服务器→客户端 1824 字节,ServerHello、Certificate、ServerKeyExchange、CertificateRequest、ServerHelloDone、NewSessionTicket……全是明文握手消息,路径上的设备可以直接读出客户端证书和里面的身份。TLS 1.3:客户端→服务器 2583 字节,除了 ClientHello 之外只有 ChangeCipherSpec 和 4 个加密记录(860、95、69、19 字节);服务器→客户端 3800 字节,ServerHello 之后同样全是加密记录——CertificateRequest、客户端的 Certificate 和 CertificateVerify 都被藏在加密记录里了。", t=tl(S(4)), mark=lidx(S(4), 'TLS 1.2:客户端→服务器', 'TLS 1.3:客户端→服务器'), done=lidx(S(4), 'TLS 1.2 里服务器的'), b=bars([['TLS 1.2 客户端→服务器(明文握手)', 1232, '1232 字节'], ['TLS 1.3 客户端→服务器(加密记录)', 2583, '2583 字节']], 2583, mark=[0], done=[1]), kv=KV([['TLS 1.2', 'CertificateRequest、客户端 Certificate 明文可见'], ['TLS 1.3', '除 ClientHello / ServerHello 外全部加密']], ['TLS 1.2'])),
    step("双向认证的代价。lo0 上 TLS 1.3,服务器不要 / 要求客户端证书,各做 150 次新连接握手:单向 TLS 中位 0.72 ms(p90 0.78 ms);双向 TLS(客户端出示证书)中位 0.87 ms(p90 0.99 ms)。多了约 0.15 ms(21%)——客户端要多发一个证书和一个 CertificateVerify 签名,服务器要多验证一条证书链和一个签名。这是在回环上测的,没有网络延迟,所以这个差就是纯计算和消息处理;到了真实网络上,额外的往返字节(约 1~2 KB)也会有影响。", t=tl(S(5)), mark=lidx(S(5), '单向 TLS', '双向 TLS'), done=lidx(S(5), '双向认证比单向多约'), b=bars([['单向 TLS 中位', 0.72, '0.72 ms'], ['双向 TLS 中位', 0.87, '0.87 ms']], 0.9, mark=[1], done=[0]), kv=KV([['单向 TLS', '0.72 ms'], ['双向 TLS', '0.87 ms(+0.15 ms,+21%)'], ['测量环境', 'lo0 回环,无网络延迟']], ['双向 TLS'])),
]
A = mkartw('w94', 94, '网络协议,TLS,mTLS,双向认证,客户端证书,CertificateRequest,真实验证,动画演示',
    '本机用临时生成的小 PKI 实测双向 TLS:有效证书握手 1.7 ms 成功,不带证书 / 不被信任的 CA / 已过期都在 TLS 1.3 里先 “握手成功” 再在第一次读时收到警报;CERT_OPTIONAL 允许不出示但不允许出示无效的;TLS 1.2 里客户端证书明文可见,TLS 1.3 里加密;双向比单向每次握手多约 0.15 ms(21%)。',
    '常见的 HTTPS 只验证服务器;双向 TLS(mTLS)让客户端也出示证书,服务器据此知道“你是谁”,在服务之间的通信和零信任网络里很常用。这篇在本机用脚本生成 CA 和几张客户端证书,把握手的成功和各种失败、线上的可见性以及额外的代价逐个量一遍。',
    [('0.72 → 0.87 ms', '本机 TLS 1.3 单向与双向握手耗时中位数'), ('假成功', 'TLS 1.3 里没带客户端证书时,客户端握手返回成功,第一次读才收到 certificate required 警报'), ('明文 vs 加密', 'TLS 1.2 里客户端证书在线上明文可见,TLS 1.3 里藏在加密记录里')],
    [('小 PKI', '<p>CA、服务器证书、有效 / 不被信任 / 已过期的客户端证书,全是临时生成的。Python 3.13 起对缺少 AKI / SKI 的证书严格拒绝。</p>'),
     ('REQUIRED', '<p>有效证书成功;没证书、不被信任、已过期在 TLS 1.3 里都是第一次读才失败,错误码分别是 certificate required / unknown ca / certificate expired。</p>'),
     ('OPTIONAL', '<p>不出示可以进(身份 None);出示无效证书仍然失败。</p>'),
     ('隐私', '<p>TLS 1.2 里客户端证书明文传输,TLS 1.3 里加密。</p>'),
     ('代价', '<p>双向比单向每次握手多约 0.15 ms(回环上)。</p>')],
    steps,
    [ENV_W + '。全部在本机 lo0:服务器和客户端都是 Python ssl,证书是用 cryptography 临时生成的(使用后删除),不涉及任何真实身份或外部服务;第五节只比较了回环上的握手计算,没有网络延迟;抓包只列握手消息类型,没有解密',
     '没有验证:证书吊销(CRL / OCSP)对客户端证书的检查;证书链多级的 mTLS;客户端证书与 HTTP 认证头的配合;硬件密钥或智能卡里的客户端私钥;服务网格(Envoy、Istio)里的 mTLS 证书轮换;CertificateRequest 里 certificate_authorities 列表的内容'],
    '双向 TLS')
